# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SINIFIMDA VE OKUL BAHÇESİNDE (فِي الصَّفِّ وَفِي فِنَاءِ الْمَدْرَسَةِ)</text>\n  <rect x="20" y="46" width="320" height="194" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Sınıf İçi Ders Araç Gereçleri (فِي الصَّفِّ)</text>\n  <text x="40" y="98" font-size="12" fill="#1e3a8a">• سَبُّورَةٌ ذَكِيَّةٌ (Sebbûretün zekiyyetün): Akıllı tahta</text>\n  <text x="40" y="122" font-size="12" fill="#1e3a8a">• حَقِيبَةٌ (Hakîbetün): Çanta · كِتَابٌ: Kitap · دَفْتَرٌ: Defter</text>\n  <text x="40" y="146" font-size="12" fill="#1e3a8a">• مِقْلَمَةٌ (Miklemetün): Kalemlik · مِمْحَاةٌ: Silgi</text>\n  <text x="40" y="170" font-size="12" fill="#1e3a8a">• مِسْطَرَةٌ (Mistaratün): Cetvel · مِبْرَاةٌ: Kalemtıraş</text>\n  <text x="40" y="194" font-size="12" fill="#1e3a8a">• خَرِيطَةٌ (Harîtatün): Harita · حَاسُوبٌ: Bilgisayar</text>\n  <text x="180" y="222" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#2563eb">فِي الصَّفِّ سَبُّورَةٌ ذَكِيَّةٌ وَمَقَاعِدُ وَخَرِيطَةٌ</text>\n\n  <rect x="360" y="46" width="320" height="194" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Okul Bahçesi ve Birimler (فِنَاءُ الْمَدْرَسَةِ)</text>\n  <text x="380" y="98" font-size="12" fill="#14532d">• فِنَاءُ الْمَدْرَسَةِ (Finâü\'l-medreseti): Okul bahçesi</text>\n  <text x="380" y="122" font-size="12" fill="#14532d">• عَلَمٌ (Alemün): Bayrak · سَاحَةٌ: Alan / Saha</text>\n  <text x="380" y="146" font-size="12" fill="#14532d">• مَقْصِفٌ (Maksifun): Kantin · مُخْتَبَرٌ: Laboratuvar</text>\n  <text x="380" y="170" font-size="12" fill="#14532d">• مَكْتَبَةٌ (Mektebetün): Kütüphane · مَسْجِدٌ: Mescit</text>\n  <text x="380" y="194" font-size="12" fill="#14532d">• غُرْفَةُ الْمُدِيرِ: Müdür odası · غُرْفَةُ الْمُعَلِّمِينَ: Öğretmenler odası</text>\n  <text x="520" y="222" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">الطُّلَّابُ يَلْعَبُونَ فِي فِنَاءِ الْمَدْرَسَةِ</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">YER-YÖN ZARFLARI (ظُرُوفُ الْمَكَانِ) VE KONUM BİLDİRME</text>\n  <rect x="20" y="48" width="210" height="192" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">Üstünde ve Altında</text>\n  <text x="125" y="102" text-anchor="middle" font-size="13" font-weight="bold" fill="#713f12">فَوْقَ (Fevka) = Üstünde</text>\n  <text x="125" y="126" text-anchor="middle" font-size="11.5" fill="#854d0e">الْكِتَابُ فَوْقَ الطَّاوِلَةِ</text>\n  <text x="125" y="146" text-anchor="middle" font-size="11" fill="#854d0e">(Kitap masanın üstündedir.)</text>\n  <text x="125" y="176" text-anchor="middle" font-size="13" font-weight="bold" fill="#713f12">تَحْتَ (Tahte) = Altında</text>\n  <text x="125" y="200" text-anchor="middle" font-size="11.5" fill="#854d0e">الْحَقِيبَةُ تَحْتَ الْمَقْعَدِ</text>\n  <text x="125" y="220" text-anchor="middle" font-size="11" fill="#854d0e">(Çanta sıranın altındadır.)</text>\n\n  <rect x="245" y="48" width="210" height="192" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#be185d">Önünde ve Arkasında</text>\n  <text x="350" y="102" text-anchor="middle" font-size="13" font-weight="bold" fill="#831843">أَمَامَ (Emâme) = Önünde</text>\n  <text x="350" y="126" text-anchor="middle" font-size="11.5" fill="#9d174d">الْمُعَلِّمُ أَمَامَ السَّبُّورَةِ</text>\n  <text x="350" y="146" text-anchor="middle" font-size="11" fill="#9d174d">(Öğretmen tahtanın önündedir.)</text>\n  <text x="350" y="176" text-anchor="middle" font-size="13" font-weight="bold" fill="#831843">خَلْفَ (Halfe) = Arkasında</text>\n  <text x="350" y="200" text-anchor="middle" font-size="11.5" fill="#9d174d">الْحَدِيقَةُ خَلْفَ الْمَدْرَسَةِ</text>\n  <text x="350" y="220" text-anchor="middle" font-size="11" fill="#9d174d">(Bahçe okulun arkasındadır.)</text>\n\n  <rect x="470" y="48" width="210" height="192" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#7e22ce">Sağında ve Solunda</text>\n  <text x="575" y="102" text-anchor="middle" font-size="13" font-weight="bold" fill="#581c87">يَمِينَ (Yemîne) = Sağında</text>\n  <text x="575" y="126" text-anchor="middle" font-size="11.5" fill="#6b21a8">الْمُخْتَبَرُ يَمِينَ الصَّفِّ</text>\n  <text x="575" y="146" text-anchor="middle" font-size="11" fill="#6b21a8">(Laboratuvar sınıfın sağındadır.)</text>\n  <text x="575" y="176" text-anchor="middle" font-size="13" font-weight="bold" fill="#581c87">يَسَارَ (Yesâra) = Solunda</text>\n  <text x="575" y="200" text-anchor="middle" font-size="11.5" fill="#6b21a8">الْمَكْتَبَةُ يَسَارَ الْمَسْجِدِ</text>\n  <text x="575" y="220" text-anchor="middle" font-size="11" fill="#6b21a8">(Kütüphane mescidin solundadır.)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SINIF İÇİ EMİR KALIPLARI VE SOSYAL İFADELER</text>\n  <rect x="25" y="48" width="315" height="192" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Erkek Öğrenciye Hitap (مُذَكَّر)</text>\n  <text x="45" y="100" font-size="12" fill="#155e75">• اِفْتَحْ كِتَابَكَ! (Kitabını aç!)</text>\n  <text x="45" y="124" font-size="12" fill="#155e75">• أَغْلِقْ دَفْتَرَكَ! (Defterini kapat!)</text>\n  <text x="45" y="148" font-size="12" fill="#155e75">• اِجْلِسْ مَكَانَكَ! (Yerine otur!)</text>\n  <text x="45" y="172" font-size="12" fill="#155e75">• اِقْرَأِ الدَّرْسَ! (Dersi oku!)</text>\n  <text x="45" y="196" font-size="12" fill="#155e75">• اُكْتُبْ عَلَى السَّبُّورَةِ! (Tahtaya yaz!)</text>\n  <text x="182" y="224" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#0891b2">اِسْتَمِعْ إِلَى الْمُعَلِّمِ! (Öğretmeni dinle!)</text>\n\n  <rect x="360" y="48" width="315" height="192" rx="8" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#c2410c">Kız Öğrenciye Hitap (مُؤَنَّث)</text>\n  <text x="380" y="100" font-size="12" fill="#9a3412">• اِفْتَحِي كِتَابَكِ! (Kitabını aç!)</text>\n  <text x="380" y="124" font-size="12" fill="#9a3412">• أَغْلِقِي دَفْتَرَكِ! (Defterini kapat!)</text>\n  <text x="380" y="148" font-size="12" fill="#9a3412">• اِجْلِسِي مَكَانَكِ! (Yerine otur!)</text>\n  <text x="380" y="172" font-size="12" fill="#9a3412">• اِقْرَئِي الدَّرْسَ! (Dersi oku!)</text>\n  <text x="380" y="196" font-size="12" fill="#9a3412">• اُكْتُبِي عَلَى السَّبُّورَةِ! (Tahtaya yaz!)</text>\n  <text x="517" y="224" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#ea580c">رُتْبَةُ الْعِلْمِ أَعْلَى الرُّتَبِ · مُمْتَاز! · طَبْعًا!</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
